
use super::*;use std::io;
#[path="../fixtures/original_policies/ui_actions_normalizer_binding.rs"]mod original;
struct Memory{rows:Vec<(Proc,Vec<(usize,String)>)>,touched:RefCell<Vec<String>>,fail_name:Option<String>}
impl Memory{fn new(files:&[(&str,&str)])->Self{let mut rows=vec![];for(rel,text)in files{let file=crate::tree::SourceFile::from_text(rel,text);let clean=file.clean();for proc in crate::dm::dx::procs_in(&file){let body=(0..proc.body_len).map(|k|(proc.body_start+k,clean.line(proc.body_start+k).to_owned())).collect();rows.push((proc,body));}}Self{rows,touched:RefCell::new(vec![]),fail_name:None}}fn root(&self)->&Proc{&self.rows.iter().find(|(p,_)|p.name=="act_go").unwrap().0}}
struct Work{polls:usize,fail:usize,left:usize}impl Control for Work{type Error=io::Error;const CHECKED:bool=true;fn checkpoint(&mut self)->io::Result<()>{self.polls+=1;if self.polls==self.fail{Err(io::Error::from_raw_os_error(1450))}else{Ok(())}}fn reserve(&mut self,n:usize)->io::Result<()>{self.left=self.left.checked_sub(n).ok_or(io::ErrorKind::OutOfMemory)?;Ok(())}fn overflow(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}fn allocation_failed(&mut self)->io::Error{io::ErrorKind::OutOfMemory.into()}}
impl Sources<Work> for Memory{fn named(&self,name:&str,c:&mut Work)->io::Result<Rc<Vec<Proc>>>{c.checkpoint()?;self.touched.borrow_mut().push(name.to_owned());if self.fail_name.as_deref()==Some(name){return Err(io::Error::from_raw_os_error(1450))}let mut out=vec![];for(proc,_)in &self.rows{c.checkpoint()?;if proc.name==name{kc::row(c,&mut out)?;out.push(copied_proc(proc,c)?);}}Ok(Rc::new(out))}fn lines(&self,proc:&Proc,c:&mut Work,visit:&mut dyn FnMut(usize,&str,&mut Work)->io::Result<bool>)->io::Result<()>{let row=self.rows.iter().find(|(p,_)|p.rel==proc.rel&&p.line==proc.line&&p.name==proc.name).ok_or_else(||io::Error::other("test source body not issued"))?;for(number,text)in &row.1{c.checkpoint()?;if !visit(*number,text,c)?{break}}Ok(())}}
fn run(source:&Memory,c:&mut Work)->io::Result<Option<usize>>{let pats=RefCell::new(HashMap::new());FirstUse{source,pats:&pats}.first_bad_use(source.root(),"value",0,c)}
fn healthy()->Work{Work{polls:0,fail:usize::MAX,left:usize::MAX}}
#[test]fn original_ui_c2_same_helper_rank_tie_depth_named_arguments_and_raw_uses(){
 let bodies=["    ui_number(value)\n","    world << value\n","    value = 1\n","    if(!value)\n        return\n    world << value\n","    if(!!value)\n        return\n","    if(isnull(value))\n        return\n    world << value\n","    switch(value)\n","    if(value == SOME_CONSTANT)\n        return\n","    helper(value)\n","    helper(key = value)\n","    src.helper(value)\n","    helper(list(1,2), value)\n"];
 for body in bodies{let root=format!("/obj/a/proc/act_go(value)\n{body}");for helper in ["/proc/helper(value)\n    ui_number(value)\n","/proc/helper(key)\n    ui_text(key)\n","/obj/a/proc/helper(value)\n    world << value\n","/proc/helper(first,second)\n    ui_text(second)\n"]{let files=[("code/a.dm",root.as_str()),("code/b.dm",helper)];let source=Memory::new(&files);assert_eq!(run(&source,&mut healthy()).unwrap(),original::original_ui_first_bad(&files,"/obj/a","act_go","value"),"{body} / {helper}");}}
 let root="/obj/a/proc/act_go(value)\n    helper(value)\n";let bad="/obj/a/proc/helper(value)\n    world << value\n";let good="/obj/a/proc/helper(value)\n    ui_number(value)\n";for files in [vec![("code/a.dm",root),("code/foo.dm",bad),("code/foo/a.dm",good)],vec![("code/a.dm",root),("code/foo.dm",good),("code/foo/a.dm",bad)]]{let source=Memory::new(&files);assert_eq!(run(&source,&mut healthy()).unwrap(),original::original_ui_first_bad(&files,"/obj/a","act_go","value"));}
 for depth in 0..6{let mut rows=vec![("code/root.dm".to_owned(),root.to_owned())];let mut names=vec!["helper".to_owned()];for i in 0..depth{names.push(format!("hop{i}"));}for(i,name)in names.iter().enumerate(){let body=if i+1==names.len(){"    ui_number(value)\n".into()}else{format!("    {}(value)\n",names[i+1])};rows.push((format!("code/helper{i}.dm"),format!("/proc/{name}(value)\n{body}")));}let refs:Vec<_>=rows.iter().map(|(p,s)|(p.as_str(),s.as_str())).collect();let source=Memory::new(&refs);assert_eq!(run(&source,&mut healthy()).unwrap(),original::original_ui_first_bad(&refs,"/obj/a","act_go","value"),"original depth {depth}");}
}
#[test]fn ui_c2_missing_helper_is_observed_then_changes_and_first_inner_io_or_quota_is_never_a_validated_answer(){let root="/obj/a/proc/act_go(value)\n    missing(value)\n";let files=[("code/a.dm",root)];let source=Memory::new(&files);assert_eq!(run(&source,&mut healthy()).unwrap(),Some(2));assert!(source.touched.borrow().iter().any(|name|name=="missing"));let files=[("code/a.dm",root),("code/helper.dm","/proc/missing(value)\n    ui_number(value)\n")];let mut source=Memory::new(&files);assert_eq!(run(&source,&mut healthy()).unwrap(),None);source.fail_name=Some("missing".into());assert_eq!(run(&source,&mut healthy()).unwrap_err().raw_os_error(),Some(1450));source.fail_name=None;assert_eq!(run(&source,&mut healthy()).unwrap(),None);let mut failed=healthy();failed.fail=7;assert_eq!(run(&source,&mut failed).unwrap_err().raw_os_error(),Some(1450));assert_eq!(failed.polls,7);let mut denied=healthy();denied.left=1;assert_eq!(run(&source,&mut denied).unwrap_err().kind(),io::ErrorKind::OutOfMemory);}
